// Una cola de salida con reintentos, contra un servidor al que se le pierde la primera respuesta.
function nuevoServidor(idempotente) {
  const s = { talentos: 0, vistos: new Set(), respuestasPerdidas: 1 };
  s.recibir = (msg) => {
    const repetido = idempotente && s.vistos.has(msg.cliente_id);
    if (!repetido) { s.vistos.add(msg.cliente_id); s.talentos += msg.suma; }
    if (s.respuestasPerdidas > 0) { s.respuestasPerdidas--; throw new Error("sin_senal"); } // se aplicó, pero la respuesta no llegó
  };
  return s;
}

function correr(idempotente) {
  const servidor = nuevoServidor(idempotente);
  const cola = [{ cliente_id: "a1", suma: 15 }]; // el teléfono anota: «gané 15 Talentos»
  let intentos = 0;
  while (cola.length && intentos < 5) {
    intentos++;
    try { servidor.recibir(cola[0]); cola.shift(); } catch { /* queda en la cola y se reintenta */ }
  }
  return `intentos: ${intentos}, Talentos en el servidor: ${servidor.talentos}`;
}

console.log("sin cliente_id único ->", correr(false));
console.log("con cliente_id único ->", correr(true));

// Dos teléfonos editan lo mismo sin señal. Cada edición lleva el reloj del teléfono que la hizo.
const inicial = { nota: "Salmo 23", color: "amarillo" };
const edicionA = { campo: "color", valor: "verde", reloj: 10 * 60 + 0 };  // A edita a las 10:00, reloj correcto
const edicionB = { campo: "nota", valor: "Salmo 23: leído", reloj: 10 * 60 + 1 };  // B edita a las 10:01, reloj correcto

// Política 1: gana el registro completo del último reloj (último gana)
function ultimoGanaRegistro(ediciones) {
  const ganadora = [...ediciones].sort((x, y) => x.reloj - y.reloj).at(-1);
  // cada teléfono manda el registro entero con su cambio puesto
  return { ...inicial, [ganadora.campo]: ganadora.valor };
}
// Política 2: por campo, cada campo lo decide su última edición
function porCampo(ediciones) {
  const r = { ...inicial };
  for (const e of [...ediciones].sort((x, y) => x.reloj - y.reloj)) r[e.campo] = e.valor;
  return r;
}

console.log("último gana (registro entero):", JSON.stringify(ultimoGanaRegistro([edicionA, edicionB])));
console.log("por campo:                    ", JSON.stringify(porCampo([edicionA, edicionB])));
